/** The stock model photos and their precomputed pose, generated by the Python script. */
import type { Landmark } from "./pose";

export type BodyPreset = "slim" | "regular" | "plus";
export type BodyGender = "men" | "women";

export type ModelBody = {
  id: string;
  name: string;
  gender: BodyGender;
  preset: BodyPreset;
  image: string;
  width: number;
  height: number;
  landmarks: Landmark[];
};

let cached: Promise<ModelBody[]> | null = null;

export function loadBodies(): Promise<ModelBody[]> {
  if (!cached) {
    cached = fetch("/tryon/bodies/bodies.json")
      .then((response) => {
        if (!response.ok) throw new Error("Could not load the model photos.");
        return response.json() as Promise<ModelBody[]>;
      })
      .catch((error) => {
        cached = null;
        throw error;
      });
  }
  return cached;
}

export function bodyFor(bodies: ModelBody[], gender: BodyGender, preset: BodyPreset): ModelBody | null {
  return bodies.find((body) => body.gender === gender && body.preset === preset) ?? bodies.find((body) => body.gender === gender) ?? null;
}
